package com.fitness.tracker.config; import com.fitness.tracker.entity.Exercise; import com.fitness.tracker.repository.ExerciseRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; @Configuration public class SeedData {@Bean CommandLineRunner exercises(ExerciseRepository r){return a->{String[] names={"Push Ups","Squats","Plank","Walking","Running","Cycling","Jump Rope","Bench Press","Deadlift","Pull Ups"};for(String n:names)if(!r.existsByName(n)){var x=new Exercise();x.name=n;x.category="Fitness";x.muscleGroup="Full body";x.description="A practical exercise for a balanced training routine.";x.caloriesPerMinute=6.0;r.save(x);}};}}
